import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Building Ultra-Resilient Ceph Clusters with Xinnor and OSNexus","description":"","frontmatter":{"title":"Building Ultra-Resilient Ceph Clusters with Xinnor and OSNexus","date":"2026-06-09T00:00:00.000Z","updated":"2026-06-10T00:00:00.000Z","tags":["Ceph","Erasure Coding","高可用性","NVMe","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Building_Ultra-Resilient_Ceph_Clusters_with_Xinnor_and_OSNexus.md","filePath":"posts/2026/Building_Ultra-Resilient_Ceph_Clusters_with_Xinnor_and_OSNexus.md","lastUpdated":null}'),o={name:"posts/2026/Building_Ultra-Resilient_Ceph_Clusters_with_Xinnor_and_OSNexus.md"};function a(n,i,s,u,d,h){return r(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="构建超高可靠性-ceph-集群-xinnor-与-osnexus-联合方案" tabindex="-1">构建超高可靠性 Ceph 集群：Xinnor 与 OSNexus 联合方案 <a class="header-anchor" href="#构建超高可靠性-ceph-集群-xinnor-与-osnexus-联合方案" aria-label="Permalink to &quot;构建超高可靠性 Ceph 集群：Xinnor 与 OSNexus 联合方案&quot;">​</a></h1><h2 id="会议概况" tabindex="-1">会议概况 <a class="header-anchor" href="#会议概况" aria-label="Permalink to &quot;会议概况&quot;">​</a></h2><p>本次 Ceph Tech Talk 由 Ceph 社区经理 Anthony Middleton 主持，OSNexus 的 Steven 与 Xinnor（Zstor）CEO Dimitri 共同分享了如何通过<strong>双层 Erasure Coding</strong> 架构，将 Ceph 集群的可靠性从传统的 6 个 9 提升到 12 至 14 个 9，并在不牺牲性能的前提下大幅简化运维。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-单层-ceph-保护的局限性-single-layer-trap" tabindex="-1">1. 单层 Ceph 保护的局限性（Single Layer Trap） <a class="header-anchor" href="#_1-单层-ceph-保护的局限性-single-layer-trap" aria-label="Permalink to &quot;1. 单层 Ceph 保护的局限性（Single Layer Trap）&quot;">​</a></h3><p>在多站点（multi-site）部署场景下，如果仅依赖 Ceph 自身的 replica 3 或 Erasure Coding 提供数据保护，会存在一个隐藏风险：</p><ul><li>当一个站点完全故障时，剩余两个站点仍维持 <code>min_size=2</code>，业务可继续运行；</li><li>但只要剩余站点上<strong>任意一块磁盘再次发生故障</strong>，受影响的 PG（Placement Group）将无法写入，导致整个 pool 停止服务（downtime）；</li><li>若将 <code>min_size</code> 降到 1 以维持可用性，集群将在<strong>无任何数据保护</strong>的状态下运行，这是必须避免的。</li></ul><p>考虑到 HDD 年故障率约 1.5%，SSD 也有相近量级的故障率，在大规模 multi-site 集群中，&quot;站点故障 + 单盘故障&quot; 是必须正面应对的真实概率事件，而不是边角场景。</p><h3 id="_2-双层-erasure-coding-的解决思路" tabindex="-1">2. 双层 Erasure Coding 的解决思路 <a class="header-anchor" href="#_2-双层-erasure-coding-的解决思路" aria-label="Permalink to &quot;2. 双层 Erasure Coding 的解决思路&quot;">​</a></h3><p>Steven 提出的核心方案是在 OSD 之下再叠加一层节点级数据保护：</p><ul><li><strong>Layer 1（节点级）</strong>：在物理 NVMe / HDD 之上由 Xinnor xiRAID 构建带双校验（如 RAID 6 / RAID 7.3）的 RAID Pool，再切分出逻辑设备；</li><li><strong>Layer 2（集群级）</strong>：Ceph 在这些<strong>已具备容错能力的逻辑设备</strong>上创建 OSD，并继续保持双校验级别的 Erasure Coding（如 4+2、8+3）或 replica；</li><li>这种做法与 AWS、Azure、Google Cloud、Wasabi 等公有云的实现思路一致——它们均在底层用 Reed-Solomon 类编码做本地保护，再在集群范围做分布式 EC。</li></ul><p>带来的效果：</p><ul><li>单盘故障由底层 RAID 自动修复，<strong>不会触发 Ceph 的 backfill 与 deep scrub 中断</strong>；</li><li>站点故障 + 多块本地盘故障同时发生时，Ceph 集群仍保持完全健康；</li><li>整体可靠性从单层的 6–9 个 9 提升至 11–16 个 9。</li></ul><h3 id="_3-现有节点级保护方案的问题-dimitri-主讲" tabindex="-1">3. 现有节点级保护方案的问题（Dimitri 主讲） <a class="header-anchor" href="#_3-现有节点级保护方案的问题-dimitri-主讲" aria-label="Permalink to &quot;3. 现有节点级保护方案的问题（Dimitri 主讲）&quot;">​</a></h3><p>Dimitri 系统对比了几种现有的节点级数据保护技术：</p><p><strong>Hardware RAID（硬件 RAID）</strong></p><ul><li>仍适用于 HDD，但对 NVMe 已不再合适；</li><li>RAID 卡通常仅占 16 条 PCIe Lane，每块 NVMe 需 4 条 Lane，理论上<strong>最多只能服务 4 块 NVMe</strong>，实际还达不到 4 块满速；</li><li>占用宝贵的 PCIe 槽位，挤压了网络带宽资源。</li></ul><p><strong>GPU-based RAID</strong></p><ul><li>同样占用 PCIe 槽位；</li><li>GPU 仅卸载校验/EC 计算部分，其余数据路径仍跑在 CPU；</li><li>重建（rebuild）模式下性能不佳，仍受 PCIe Lane 数量限制。</li></ul><p><strong>MD RAID（开源软件 RAID）</strong></p><ul><li>除顺序读以外其他模式表现都不理想；</li><li>写操作时 CPU 核心负载不均，存在 stripe lock，需要额外内存拷贝；</li><li>Degraded 与 rebuild 模式下负载尖刺更严重。</li></ul><h3 id="_4-xiraid-的关键技术特性" tabindex="-1">4. xiRAID 的关键技术特性 <a class="header-anchor" href="#_4-xiraid-的关键技术特性" aria-label="Permalink to &quot;4. xiRAID 的关键技术特性&quot;">​</a></h3><p>Xinnor 的 xiRAID 是纯软件方案，主要差异化技术点包括：</p><ul><li>利用 <strong>AVX 指令集</strong>及自研 CPU 寄存器数据布局做高效校验计算（已申请专利），并已移植到 ARM 架构，可运行于 DPU；</li><li>自研数据路径，将读写均匀打散到所有 CPU 核心，<strong>避免负载尖刺</strong>，正常 IO 与 degraded/rebuild 模式下都保持高性能；</li><li><strong>支持范围</strong>：单 RAID Group 最多 64 块盘、最多 42 块用作校验；支持 RAID 5/6/7.3，校验盘最多可达 32 块；通过 nested RAID（RAID 50/60/70）可在单个 array 中扩展到 600 块盘；</li><li>同时提供 <strong>xiRAID Declustered RAID</strong>，目前已与 Lustre 集成，未来将集成到自身引擎中，可显著缩短 QLC 大容量盘的 rebuild 时间；</li><li>要求使用具备 <strong>Power Loss Protection</strong> 的数据中心/企业级盘。</li></ul><h3 id="_5-性能与重建实测" tabindex="-1">5. 性能与重建实测 <a class="header-anchor" href="#_5-性能与重建实测" aria-label="Permalink to &quot;5. 性能与重建实测&quot;">​</a></h3><p><strong>对比基准（xiRAID vs MD RAID(RAID 10) vs Broadcom MegaRAID）</strong></p><ul><li>顺序与随机 IO 性能均显著领先 MegaRAID；</li><li>与 MD RAID（即便用容量利用率最差的 RAID 10）相比，随机性能仍有大幅领先；</li><li>详细数据可在 SNIA Talks 录像与 Xinnor 的公开分析中查阅。</li></ul><p><strong>与 Solidigm 联合测试（9 块 60 TB QLC + RAID 5）</strong></p><ul><li>xiRAID 重建一块 60 TB 盘耗时约 <strong>50 小时</strong>；</li><li>MD RAID 在同等条件下推算需 <strong>60+ 天</strong>（基于两周测试数据外推）；</li><li>带真实 workload 的 Write Amplification Factor（WAF）控制在 <strong>1.2</strong> 左右，无 workload 时接近 1，对 QLC 乃至未来 PLC 介质寿命极为关键；</li><li>在 QLC workload 下相较无 xiRAID 场景可获得约 <strong>200 倍</strong>的性能提升。</li></ul><p><strong>工业级落地参考</strong></p><ul><li>基于 xiRAID 的 Lustre 实现已登上 <strong>IO500</strong> 榜单前列；</li><li>该方案中文件系统底层的数据保护正是由 xiRAID 提供，相同思路完全可移植到 Ceph。</li></ul><h3 id="_6-双层架构的额外收益" tabindex="-1">6. 双层架构的额外收益 <a class="header-anchor" href="#_6-双层架构的额外收益" aria-label="Permalink to &quot;6. 双层架构的额外收益&quot;">​</a></h3><p>除可靠性外，引入 Layer 1 RAID 还带来以下好处：</p><ul><li><strong>降低 OSD 数量</strong>：3000 块 NVMe 可聚合为 1000 个 OSD，提升集群可扩展性；</li><li><strong>降低 RAM 需求</strong>：每个 OSD 的缓存与元数据开销减少，整集群内存占用下降；</li><li><strong>重建本地化</strong>：所有介质故障在本地 RAID 内修复，<strong>不消耗 WAN 带宽</strong>，对 stretch cluster 尤其重要；</li><li><strong>修复窗口短</strong>：rebuild 时间缩短直接降低 Markov 链分析中的连环故障概率。</li></ul><h3 id="_7-quantastor-中的产品化集成" tabindex="-1">7. QuantaStor 中的产品化集成 <a class="header-anchor" href="#_7-quantastor-中的产品化集成" aria-label="Permalink to &quot;7. QuantaStor 中的产品化集成&quot;">​</a></h3><p>OSNexus QuantaStor 已将 xiRAID 集成进管理界面：</p><ul><li>在 Controller &amp; Enclosure 视图中，xiRAID 表现为类似 RAID 卡的对象；</li><li>用户可一键基于 N 块 NVMe 创建双校验 RAID Pool，并产出 1:1 的逻辑设备；</li><li>这些逻辑设备直接作为 OSD 加入 Ceph，对 Ceph 完全透明（&quot;none the wiser&quot;）；</li><li>支持热备盘的标记与按需添加。</li></ul><h2 id="关键问答摘录" tabindex="-1">关键问答摘录 <a class="header-anchor" href="#关键问答摘录" aria-label="Permalink to &quot;关键问答摘录&quot;">​</a></h2><ul><li><strong>xiRAID 是否支持 HDD？</strong> 支持，但 HDD 上软件 RAID 与硬件 RAID 性能相近，HDD 的差异化主要在 declustered RAID 缩短 rebuild 时间，QLC 时代同样需要这种能力。</li><li><strong>是否应使用 EC pool 提升多节点容灾？</strong> 应根据节点容灾需求合理选择 EC profile（如 7+5），但更核心的是<strong>消除跨站点 rebuild 对 WAN 的占用</strong>——这正是双层架构的核心价值。</li><li><strong>xiRAID 自身故障如何处理？</strong> 极端情况下（如长期未维护、双校验下连续 3 盘故障），即便 RAID Group 失效，上层 Ceph 的 EC/replica 仍能完整重建数据；最坏情况退到 <code>min_size=1</code>，但因下层仍有 RAID 校验信息，整体安全裕度高于纯单层方案。</li><li><strong>AWS / Azure / IBM Cloud 用什么 RAID 加速？</strong> 主流公有云普遍采用自研软件方案，IBM Cloud 的 COS 基于早期收购产品；IBM Spectrum Scale（GPFS）有自家 RAID 实现，xiRAID 也是其参考架构之一。</li></ul><h2 id="决定事项与结论" tabindex="-1">决定事项与结论 <a class="header-anchor" href="#决定事项与结论" aria-label="Permalink to &quot;决定事项与结论&quot;">​</a></h2><ol><li><strong>Dual-layer Erasure Coding 是大规模 Ceph 集群的事实标准</strong>，特别是数十至数百 PB 级、multi-site / stretch cluster 场景；</li><li>Layer 1 推荐使用 xiRAID 等纯软件、可充分发挥 NVMe 性能、且重建快速的方案；不再推荐为 NVMe 配置硬件 RAID 卡；</li><li>Layer 2 必须保持<strong>双校验或更强</strong>的 Ceph EC / replica 配置，单校验组合不被推荐；</li><li>在 QLC、未来 PLC 等大容量介质上，<strong>rebuild 时间与 WAF</strong> 是衡量底层方案的关键指标。</li></ol><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>评估当前生产 Ceph 集群在 &quot;站点故障 + 单盘故障&quot; 复合故障下的真实可用性窗口；</li><li>对 NVMe 资源池（特别是 QLC/大容量盘）规划 xiRAID 或同级别底层 EC 方案的 PoC；</li><li>在 stretch cluster 与多站点部署中，重新审视 OSD 数量、<code>min_size</code>、EC profile 与 WAN 带宽规划；</li><li>对 QuantaStor + xiRAID 的一体化部署进行复测，验证 rebuild 时间、WAF 与对 Ceph 上层 scrub / backfill 的零干扰特性；</li><li>持续关注 xiRAID Declustered RAID 在通用引擎中的发布进度，作为大容量 QLC/HDD 场景的下一步技术储备。</li></ul>',43)])])}const D=e(o,[["render",a]]);export{p as __pageData,D as default};
